export function Pill(props: IProps): JSX.Element | null {
    const { type, url, inMessage, room, shouldShowPillAvatar } = props;
    const { avatar, text, onClick, resourceId, type: resolvedType } = usePermalink({ room, type, url });

    if (!text || !resolvedType) {
        return null;
    }

    const [showTooltip, setShowTooltip] = useState(false);

    const handleClick = (e: ButtonEvent) => {
        if (onClick) {
            onClick(e);
        }
    };

    const handleMouseEnter = () => {
        if (resourceId) {
            setShowTooltip(true);
        }
    };

    const handleMouseLeave = () => {
        setShowTooltip(false);
    };

    const pillClass = classNames("mx_Pill", {
        "mx_UserPill": resolvedType === PillType.UserMention,
        "mx_RoomPill": resolvedType === PillType.RoomMention,
        "mx_AtRoomPill": resolvedType === PillType.AtRoomMention,
        "mx_SpacePill": resolvedType === "space",
