    const content = (
        <bdi className={pillClass} onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
            {shouldShowPillAvatar && avatar}
            <span className="mx_Pill_linkText">{text}</span>
            {showTooltip && resourceId && (
                <Tooltip label={resourceId} alignment={Alignment.Right}>
                    <span />
                </Tooltip>
            )}
        </bdi>
    );

    if (inMessage && url) {
        return (
            <a href={url} onClick={handleClick} className="mx_Pill">
                {content}
            </a>
        );
    } else {
        return (
            <span className="mx_Pill">
                {content}
            </span>
        );
    }
}
