import React, { useCallback, useEffect, useState } from "react";
import { Room, RoomMember } from "matrix-js-sdk/src/models/room";
import { MatrixClientPeg } from "../MatrixClientPeg";
import { PillType } from "../components/views/elements/Pill";
import { Avatar } from "../components/views/elements/Avatar";
import { Action } from "../../dispatcher";
import { _t } from "../../languageHandler";

export interface UsePermalinkArgs {
    room?: Room;
    type?: PillType;
    url?: string;
}

export interface HookResult {
    avatar: React.ReactElement | null;
    text: string | null;
    onClick: ((e: React.MouseEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

/**
 * Resolves the effective type, raw identifier, human-friendly text,
 * an optional avatar element, and an optional user onClick handler
 * for a Matrix permalink or @room mention.
 */
export function usePermalink({ room, type, url }: UsePermalinkArgs): HookResult {
    const [state, setState] = useState<HookResult>({
        avatar: null,
        text: null,
        onClick: null,
        resourceId: null,
        type: null,
    });

    useEffect(() => {
        const matrixClient = MatrixClientPeg.get();
        if (!matrixClient) return;

        let effectiveType: PillType | "space" | null = null;
        let resourceId: string | null = null;
        let text: string | null = null;
        let avatar: React.ReactElement | null = null;
        let onClick: ((e: React.MouseEvent) => void) | null = null;

        // Determine type from explicit prop or URL sigil
        if (type === PillType.AtRoomMention) {
            effectiveType = PillType.AtRoomMention;
            resourceId = "@room";
            text = "@room";
        } else if (url) {
            if (url.startsWith("@")) {
                effectiveType = PillType.UserMention;
                resourceId = url;
            } else if (url.startsWith("!") || url.startsWith("#")) {
                effectiveType = PillType.RoomMention;
                resourceId = url;
            }
        }

        if (effectiveType === null || resourceId === null) {
            setState({ avatar: null, text: null, onClick: null, resourceId: null, type: null });
            return;
        }

        if (effectiveType === PillType.UserMention) {
            const userId = resourceId!;
            const member = room?.getMember(userId);
            if (member) {
                text = member.displayName || userId;
                if (room) {
                    avatar = (
                        <Avatar
                            room={room}
                            member={member}
                            size={16}
                            ignoreSelf={true}
                        />
                    );
                }
                onClick = (e: React.MouseEvent) => {
                    e.stopPropagation();
                    matrixClient.getRoomDirectory().then(() => {
                        // Standard "view user" action
                        const action = new Action("view_user", { userId });
                        // Dispatch via the global dispatcher
                        import("../../dispatcher").then(({ dispatch }) => {
                            dispatch(action);
                        });
                    });
                };
            } else {
                // User not in room: fall back to profile lookup
                matrixClient.getProfileInfo(userId).then((profile) => {
                    text = profile?.displayName || userId;
                    if (profile?.avatarUrl) {
                        avatar = (
                            <Avatar
                                room={room}
                                member={null}
                                size={16}
                                url={profile.avatarUrl}
                            />
                        );
                    }
                    setState({
                        avatar,
                        text,
                        onClick,
                        resourceId: userId,
                        type: PillType.UserMention,
                    });
                }).catch(() => {
                    setState({
                        avatar: null,
                        text: userId,
                        onClick: null,
                        resourceId: userId,
                        type: PillType.UserMention,
                    });
                });
                return;
            }
        } else if (effectiveType === PillType.RoomMention) {
            const roomIdOrAlias = resourceId!;
            if (room) {
                const resolvedRoom = matrixClient.getRoom(roomIdOrAlias) || (roomIdOrAlias.startsWith("!") ? matrixClient.getRoom(roomIdOrAlias) : null);
                if (resolvedRoom) {
                    text = resolvedRoom.name || roomIdOrAlias;
                    if (resolvedRoom.isSpace) {
                        effectiveType = "space";
                    }
                    avatar = (
                        <Avatar
                            room={resolvedRoom}
                            member={null}
                            size={16}
                        />
                    );
                } else {
                    text = roomIdOrAlias;
                }
            } else {
                text = roomIdOrAlias;
            }
        } else if (effectiveType === PillType.AtRoomMention) {
            if (room) {
                avatar = (
                    <Avatar
                        room={room}
                        member={null}
                        size={16}
                    />
                );
            }
        }

        setState({
            avatar,
            text,
            onClick,
            resourceId,
            type: effectiveType,
        });
    }, [room, type, url]);

    return state;
}
